// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;
    function setUp() public { c = new RewardVault(); }
    function testFuzz_property(address user, uint256 depositAmount) public {
        vm.assume(user != address(0) && depositAmount > 0 && depositAmount <= type(uint96).max);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();
        vm.prank(user);
        c.claim();
        assertTrue(c.reward(user) > 0 || c.balance(user) * c.rateSnapshot(user) == 0, "reward not updated");
    }
}
